#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperationsToUniform(std::vector<int>& nums) {
        int odds = 0;
        for (int x : nums) if (x % 2 != 0) odds++;
        int evens = nums.size() - odds;
        return std::min(odds, evens);
    }
};

class Solution {
    public int minOperationsToUniform(int[] nums) {
        int odds = 0;
        for (int x : nums) if (x % 2 != 0) odds++;
        int evens = nums.length - odds;
        return Math.min(odds, evens);
    }
}

